AssignmentStatement: lhs is [Location: type.name matches "unsigned.*"]*
    and rhs is [Location l: type.name matches "char|short|int|long"
        /* is not a constant value */
        and constantValue.null
        /* not some sort of length, which are usually false positives */
        and not l is [FieldAccess: field.name matches ".*len(gth)?|.*size" ]
        and not l is [VariableAccess: variable.name matches ".*len(gth)?|.*size"]
    ]*

AssignmentStatement: lhs is [Location: type.name matches "unsigned.*"]*
    and rhs is [Location l: type.name matches "char|short|int|long"
        /* is not a constant value */
        and constantValue.null
        /* not some sort of length, which are usually false positives */
        and not l.name matches ".*len(gth)?|.*size"
        /* not a binary value from a synthetic if-else block */
        and not (
            l.constantValues.length == 2
            and l.constantValues contains [Number: == 0]
            and l.constantValues contains [Number: == 1]
        )
    ]*

ReturnStatement rs:
    rs.enclosingFunction is [Function: ]* and rs.enclosingFunction.returnType is
        [name matches "unsigned.*" or indirectionLevel > 0]
        /* Needed because literals are always signed. */
        and not rs.expression.constantValue is [Number: >= 0]
    and rs.expression.type is [
        indirectionLevel == 0 and
        name is [ == "char" or == "short" or == "int" or == "long"]]
    /* Don't duplicate results caught by the "Negative return value" rule. */
    and not rs.expression.partialConstantValues contains [Number: < 0]
    and not rs.enclosingFunction contains [IfStatement:
        expression is [Operation o:
            rs.expression is [VariableAccess: variable is [Variable v: 
                (
                    o.lhs.location is [VariableAccess: 
                        variable is v
                    ]
                    and o.op matches ">(=)?"
                    and (
                        o.rhs.type.unsigned
                        or o.rhs.constantValue is [Number: >= 0]
                    )
                )
                or (
                    o.op matches "<(=)?"
                    and o.rhs.location is [VariableAccess:
                        variable is v
                    ]
                )
            ]]
            or rs.expression is [FieldAccess: field is [Field f: 
                (
                    o.lhs.location is [FieldAccess: 
                        field is f
                    ]
                    and o.op matches ">(=)?"
                    and (
                        o.rhs.type.unsigned
                        or o.rhs.constantValue is [Number: >= 0]
                    )
                )
                or (
                    o.op matches "<(=)?"
                    and o.rhs.location is [FieldAccess: 
                        field is f
                    ]
                )
            ]]
        ]
    ]

StructuralRule.Notes:
This rule catches the following case:
                            buf = realloc(buf, 256);
                            free(buf);
                            This rule will produce duplicates due to other rules catching the same issue for the following case:
                            buf = realloc(buf, 256);

