CharacterizationRule.Definition:
std::__1 / {istream.get,basic_istream.get} (dest) {
    BufferWrite(dest, 0, 1)
    Ensures(dest.$size' == dest.$size)
    Ensures(dest.$offset' == dest.$offset)
    Ensures(dest.$strlen' == ((dest.$strlen == 0) ? int.$unbounded : dest.$strlen))
}

std / {istream.get,basic_istream.get} (dest) {
    BufferWrite(dest, 0, 1)
    Ensures(dest.$size' == dest.$size)
    Ensures(dest.$offset' == dest.$offset)
    Ensures(dest.$strlen' == ((dest.$strlen == 0) ? int.$unbounded : dest.$strlen))
}

std::__1 / {istream.getline,istream.get,basic_istream.getline,basic_istream.get} (dest, size, delim) {
