    BufferWrite(dest, 0, min(256, src.$strlen + 1))
    Ensures(dest.$size' == dest.$size)
    Ensures(dest.$offset' == dest.$offset)
    Ensures(dest.$strlen' <= min(255, src.$strlen))
    Ensures(dest.$strlen' >= 0)
}

PathCombineW(dest,path,file) {
    //BufferRead(path, 0, path.$strlen*sizeof(wchar_t))
    //BufferRead(file, 0, file.$strlen*sizeof(wchar_t))
    BufferWrite(dest, 0, min(256, path.$strlen + file.$strlen + 1)*sizeof(wchar_t))
    Ensures(dest.$size' == dest.$size)
    Ensures(dest.$offset' == dest.$offset)
    Ensures(dest.$strlen' <= min(255, path.$strlen + file.$strlen))
    Ensures(dest.$strlen' >= 0)
}

