    //BufferRead(src,0,min(src.$strlen*sizeof(wchar_t), max))
    BufferWrite(dest,dest.$strlen*sizeof(wchar_t),min(min(src.$strlen*sizeof(wchar_t), max) + sizeof(wchar_t), size - dest.$strlen*sizeof(wchar_t)))
    Ensures(dest.$size' == dest.$size)
    Ensures(dest.$offset' == dest.$offset)
    Ensures(dest.$strlen'*sizeof(wchar_t) == min(size - sizeof(wchar_t), min(src.$strlen*sizeof(wchar_t),max) + dest.$strlen*sizeof(wchar_t)))
