        BufferWrite(dest,0,min(size, FormatExpandLen(wchar_t,fmt,va_list) + 1)*sizeof(wchar_t))
        Ensures(dest.$strlen' == min(size - 1, FormatExpandLen(wchar_t,fmt,va_list)))
        Ensures(dest.$offset' == dest.$offset)
        Ensures(dest.$size' == dest.$size)
        Ensures(return == min(size - 1, FormatExpandLen(wchar_t,fmt,va_list)))
    }

