var p;
var s;

start               -> assignedNull { p = null }

assignedNull        -> surrogateAsgnNull { s =  @p  == null }
assignedNull        -> surrogateAsgnNull { s = null ==  @p  }
assignedNull        -> surrogateAsgnNot  { s =  @p  != null }
assignedNull        -> surrogateAsgnNot  { s = null !=  @p  }

